-- Paŝoj al plena posedo : réponses types (« corrigé type » montré aux correcteurs), lot 7 : leçons 25 à 28.
-- Questions sur le texte et analyses de langue (25.3, 26.3, 27.3, 28.3), passif (25.4), phrases à corriger (26.4, 27.4, 28.4),
-- définitions et proverbes (26.4).
-- Rédigées d'après les textes et les réponses cochées « juste » par les correcteurs ; à relire par Emmanuelle.
-- Ne remplace pas une réponse type existante ; peut être rejoué sans risque.
SET NAMES utf8mb4;

UPDATE ekzerceroj SET respondo = 'Ekzemple, kun la francaj nomoj. Arboj: piceo (épicéa), pino (pin), betulo (bouleau), frakseno (frêne), citizo (cytise), tujo (thuya), kameciparido (faux-cyprès), abio (sapin), acero (érable), ulmo (orme), sorpo (sorbier), ĉerizarbo (cerisier). Plantoj: leondento (pissenlit), fragmito (roseau), tifao (massette), plantaga alismo (plantain d’eau), urtiko (ortie), eriko (bruyère), mirtelo (myrtille), lapo (bardane), asperulo (aspérule), hundolango (cynoglosse), galio (gaillet), agrimonio (aigremoine), violo (violette), primolo (primevère), balzamino (balsamine). Bestoj: sturno (étourneau), pasero (moineau), urso (ours), formiko (fourmi).' WHERE id = 1993 AND ekzerco_id = 249 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Persona respondo. Ekzemple, en la franca multaj popolaj nomoj similas: leondento = dent-de-lion (pissenlit), neforgesumino = ne-m’oubliez-pas (myosotis), neĝborulo = perce-neige, orpluvo = pluie d’or (cytise), vergo d’oro = verge d’or, hundolango = langue-de-chien, kaskofloro = casque de Jupiter (aconit), kavalirsprono = pied-d’alouette, terpiro = poire de terre (topinambour).' WHERE id = 1994 AND ekzerco_id = 249 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ili estas ŝercaj, eŭfemismaj nomoj por la ekskrementoj de bovino kaj de ĉevalo, laŭ ilia formo (plata kiel kuko, ronda kiel piro).' WHERE id = 1995 AND ekzerco_id = 249 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = '“Trideko da jaroj” estas proksimuma kvanto (ĉirkaŭ tridek jaroj); “tridek jaroj” estas preciza nombro.' WHERE id = 1996 AND ekzerco_id = 249 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'malproksima' WHERE id = 1997 AND ekzerco_id = 249 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La aŭtoro parolas pri la betulo kvazaŭ ĝi estus malamiko, kiu intence turmentas ilin: ĝi invadas la tutan terenon kaj devigas ilin multe labori por forigi ĝin.' WHERE id = 1998 AND ekzerco_id = 249 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'ĝis tia grado (aŭ: en tia grado)' WHERE id = 1999 AND ekzerco_id = 249 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'tra la aero (aŭ: per la aero)' WHERE id = 2000 AND ekzerco_id = 249 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = '“Gusti” (netransitiva) estas havi guston: “la nukseto gustas bone”. “Gustumi” (transitiva) estas provi ion per la buŝo por koni ĝian guston: “ni gustumis la nukseton”.' WHERE id = 2001 AND ekzerco_id = 249 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = '“Transformita” estas predikativo de la objekto (ni imagis la parkon kiel transformitan, t.e. ke ĝi estas transformita): la predikativo de objekto restas en nominativo. Kontraŭe “lasitan” estas epiteto de “parkon”, do akuzativa.' WHERE id = 2002 AND ekzerco_id = 249 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Personigo: “la naturo embuskas ĉie” (kiel malamiko aŭ ĉasisto). Metaforo: “se ni lasas la bridon”, “la senbridigita socio de plantoj” (la naturo kiel ĉevalo, kiun oni devas bridi).' WHERE id = 2003 AND ekzerco_id = 249 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: infaneco (infan-ec-o), knabineto (knab-in-et-o), eliris (el-ir-is), finflorintaj (fin-flor-int-aj), iomete (iom-et-e), volbitan (volb-it-an), malgrandan (mal-grand-an), okupita (okup-it-a), portanta (port-ant-a), unuigitaj (unu-ig-it-aj), leviĝis (lev-iĝ-is), nubeto (nub-et-o), startejo (start-ej-o), turniĝis (turn-iĝ-is), disflugis (dis-flug-is), disportita (dis-port-it-a), ventetoj (vent-et-oj), malaperis (mal-aper-is), patrina (patr-in-a).' WHERE id = 2004 AND ekzerco_id = 249 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ambaŭ esprimas celon. “…prizorgas, ke … estu forportataj”: la -u-finaĵo sekvas verbon, kiu esprimas zorgon aŭ intencon (la hokoj “zorgas por tio, ke…”). “…por ke la semo ĝermu”: post “por ke” oni ĉiam uzas la -u-finaĵon.' WHERE id = 2005 AND ekzerco_id = 249 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: la ruzo de la ligna ĉevalo de Trojo; la sirenoj, kies kanton li aŭskultis ligita al la masto; Circe, kiu transformis liajn kunulojn en porkojn; la lotofagoj; Skilo kaj Karibdo; la nimfo Kalipso; la reveno al Itako kaj la venĝo kontraŭ la svatantoj de Penelopa.' WHERE id = 2006 AND ekzerco_id = 249 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Daŭrigita (milita) metaforo kun personigo: la balzaminoj estas prezentataj kiel armeo, kiu antaŭeniras kaj okupas teritorion (“fronto”, “trupoj”, “okupadis”).' WHERE id = 2007 AND ekzerco_id = 249 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Sed se ekzistos la plej alta institucio, elektita de la tuta esperantistaro, tiam miaj manoj estos liberigitaj, kaj ĉion, kion mi trovos utila, mi povos kuraĝe proponi al la decido de tiu institucio, kaj ĉio, kion tiu institucio decidos, povos esti kuraĝe farata, kaj neniu havos la rajton protesti aŭ disputi.' WHERE id = 2008 AND ekzerco_id = 250 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Multe da personoj estis mortigitaj. Kompreneble nenia rezultato estis atingita, ĉar la bone armita kaj senkompata soldataro montriĝis multe pli forta ol la malfeliĉa tute senarma popola amaso.' WHERE id = 2009 AND ekzerco_id = 250 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Devas esti dirite, ke, kiam la firmo ĉesos pagadi al mi la minimumon, tiam la kontrakto perdas sian leĝan valoron kaj mi fariĝas tute libera kaj mi povas eldonadi mem ĉiujn miajn verkojn, ne sole tiujn, kiuj estos faritaj de mi, sed ankaŭ tiujn, kiuj estis faritaj.' WHERE id = 2010 AND ekzerco_id = 250 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Se mi bezonos presi iajn artikolojn pri Esperanto, mi penos ĉiam fari tion ĉi en tiuj gazetoj, kiuj estos eldonataj de Hachette.' WHERE id = 2011 AND ekzerco_id = 250 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Persono, de kiu Esperanto iam estis ellernita, devas havi plenan certecon, ke neniu vorto, kiun li ellernis, iam perdos sian valoron kaj ke li neniam estos malkomprenata de aliaj esperantistoj.' WHERE id = 2012 AND ekzerco_id = 250 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: “Ĉi tiun pliriĉigon de la antaŭkristnaska manĝokarto kvitancis la tuta familio kun dankemo”; “ŝi estis de la familia konsilantaro voĉdone superita”; “Post ĉi tiu grava konstato estis la taskoj dividitaj”; “rekonsciiĝis kaj organizis sin pluaj taĉmentoj”; “solidigi la fortojn por plua, eble jam fine decidiga fazo de la batalo”; la bilanco de “hom-perdoj” kaj “material-perdoj”; “estro de la ĉefa stabo”; “transdonita al la milita tribunalo”.' WHERE id = 2022 AND ekzerco_id = 254 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: “ĉi-tiufoje detruiĝis nur vitro de la libroŝranko”; “kelkajn el tiuj aĵoj li sukcesis detrui komplete, aliajn nur parte”; “Dank’ al Dio, okazis nenio … sed la aŭtomobilojn riparos neniu plu”; “kio estis granda avantaĝo — por la leporo, kompreneble”; “mi rangaltiĝis je unua rezervulo, ĉar mi nokaŭtis la aveton”.' WHERE id = 2023 AND ekzerco_id = 254 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: “mortigadis” en la titolo (la mortigo daŭras senfine kaj neniam sukcesas), mortigado, ekkuregis, kuregi, forkuradis, forlasadis, ĵetegis, ĵetegadis, ĉaspeladis, persekutado, kolerego, ekbategos, ekkriegis.' WHERE id = 2024 AND ekzerco_id = 254 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La patro: kolerema, perforta kaj mallerta (li rompas ĉion kaj disdonas kapofrapojn). La patrino: pasiva kaj ploranta. La avino: aŭtoritata estro de la familio, ĉiam kontraŭa kaj ĉiam “prava”. Fabiano: maldiligenta profitanto, kiu ebriiĝas per la likvoro. La aŭtoro: petola, iom impertinenta bubo, kiu rakontas kun ŝajne naiva ironio.' WHERE id = 2025 AND ekzerco_id = 254 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'tiumaniere: tiel (aŭ: tiamaniere); haltigiloj: bremsoj' WHERE id = 2026 AND ekzerco_id = 254 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Oni decidis (aŭ: Ni decidis).' WHERE id = 2027 AND ekzerco_id = 254 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = '“…ĉar estis necese solidigi la fortojn por plua, eble jam fine decidiga fazo de la batalo”: post horoj da malsukceso ili ankoraŭ esperas, ke la venonta fazo estos la decida.' WHERE id = 2028 AND ekzerco_id = 254 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'sobriĝo (aŭ: elebriiĝo)' WHERE id = 2029 AND ekzerco_id = 254 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'kuirĉambro' WHERE id = 2030 AND ekzerco_id = 254 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La paro “je kio … je tio” ne esprimas proporcion kaj estas mallerta; oni dirus: “Ju pli ridinda li estis, des pli severa li volis esti.”' WHERE id = 2031 AND ekzerco_id = 254 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Tia estis la lernejo.' WHERE id = 2032 AND ekzerco_id = 255 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'En la festvespero oni prezentis teatraĵeton, verkitan de la prezidanto.' WHERE id = 2033 AND ekzerco_id = 255 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La ĉeestantoj larĝe malfermis siajn monujojn por kunhelpi en la starigo de la monumento.' WHERE id = 2034 AND ekzerco_id = 255 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ni legu tiun libron, ĉar estas grave koni la opinion de la aŭtoro.' WHERE id = 2035 AND ekzerco_id = 255 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ili konsideris Esperanton kiel ekzotikan aspiron.' WHERE id = 2036 AND ekzerco_id = 255 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La nova kurso komenciĝos post du semajnoj.' WHERE id = 2037 AND ekzerco_id = 255 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ni tre ĝojus, se vi povus plenumi nian peton.' WHERE id = 2038 AND ekzerco_id = 255 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La aliĝoj estos akceptataj nur ĝis la fino de junio.' WHERE id = 2039 AND ekzerco_id = 255 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ni forigu la malsaton en la neevoluintaj landoj! (“evolui” estas netransitiva: -iĝ- estas superflua.)' WHERE id = 2040 AND ekzerco_id = 255 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La homa socio daŭre ŝanĝiĝas.' WHERE id = 2041 AND ekzerco_id = 255 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Prepari manĝaĵon per varmo (bolante, fritante, rostante ktp.).' WHERE id = 2052 AND ekzerco_id = 257 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Memfida kaj trankvila sinteno, sen ia ajn embaraso, ofte iom aroganta.' WHERE id = 2053 AND ekzerco_id = 257 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Oblikva surfaco de tereno, kiu iras malsupren aŭ supren (ekz. monta deklivo).' WHERE id = 2054 AND ekzerco_id = 257 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Konforma al la justeco: kiu donas al ĉiu tion, kion li meritas aŭ rajtas; senpartia.' WHERE id = 2055 AND ekzerco_id = 257 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Malgranda fenestro aŭ aperturo en oficejo, stacidomo, teatro ktp., tra kiu oficisto servas la publikon (vendas biletojn, ricevas leterojn…).' WHERE id = 2056 AND ekzerco_id = 257 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Preni likvaĵon el ujo aŭ fonto per kulero, sitelo aŭ alia ilo; figure: preni el iu fonto (ĉerpi informojn).' WHERE id = 2057 AND ekzerco_id = 257 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Malglatigi ŝtofon aŭ paperon per premado, tiel ke ĝi kovriĝas per neregulaj faldoj.' WHERE id = 2058 AND ekzerco_id = 257 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Trovi la respondon aŭ la veron per supozo aŭ intuicio, sen certaj sciaĵoj.' WHERE id = 2059 AND ekzerco_id = 257 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Helflava, orkolora (pri haroj).' WHERE id = 2060 AND ekzerco_id = 257 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'El malbona komenco aŭ malbonaj rimedoj ne povas veni bona rezulto.' WHERE id = 2068 AND ekzerco_id = 259 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Sperto donas lertecon: kiu multe spertis, tiun oni ne facile trompas.' WHERE id = 2069 AND ekzerco_id = 259 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Kiu edziĝas tro maljuna, tiu riskas morti, antaŭ ol liaj infanoj plenkreskos.' WHERE id = 2070 AND ekzerco_id = 259 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Fari ion absurdan kaj vanan: provi akiri ion de tiu, kiu tute ne povas doni ĝin.' WHERE id = 2071 AND ekzerco_id = 259 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ju pli saĝa estas homo, des malpli li parolas senpripense.' WHERE id = 2072 AND ekzerco_id = 259 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = '“La nokto”: temas pri unu konkreta, difinita nokto, kiun precizigas “de la 25-a de januaro”. “La 25-a”: en datoj la orda numeralo ĉiam havas la artikolon, ĉar ĝi indikas unu difinitan tagon de la monato.' WHERE id = 2142 AND ekzerco_id = 261 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉar oni atendus, ke anglalingvanoj komprenas Burns sen traduko; sed liaj plej bonaj poemoj estas verkitaj en la skota, kiu malfortiĝas kaj ne plu estas bone komprenata, do eĉ anglalingvanoj bezonas tradukojn.' WHERE id = 2074 AND ekzerco_id = 261 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉar la poemoj estas verkitaj en la skota, lingvo malmulte konata ekster Skotlando, kaj tamen milionoj legas ilin en traduko: ilia sukceso do venas ĉefe de la universala enhavo (demokratio, frateco, amo, simpatio). Persona opinio: ne tute, ĉar ankaŭ la muziko kaj la stilo de la versoj kontribuas, kaj bona traduko redonas parton de ili.' WHERE id = 2075 AND ekzerco_id = 261 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La dorlothundo (Caesar) estas luksa hundo de riĉa terposedanto, dorlotata kaj senlabora; la ŝafhundo (Luath) estas laborhundo de malriĉa plugisto, kiu gardas la ŝafojn.' WHERE id = 2076 AND ekzerco_id = 261 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Liaj emocioj kaj impulsoj ofte estis pli fortaj ol lia racio.' WHERE id = 2077 AND ekzerco_id = 261 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'krudmane: per krudaj manoj, senkompate kaj perforte; trankvilanime: kun trankvila animo; ĉiujare: ĉiun jaron (aŭ: en ĉiu jaro).' WHERE id = 2078 AND ekzerco_id = 261 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'drinkejo (aŭ: gastejo, taverno)' WHERE id = 2079 AND ekzerco_id = 261 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉar li malamis hipokritecon, Burns verkis satirojn…' WHERE id = 2080 AND ekzerco_id = 261 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La rango (titolo, nobeleco) estas nur la stampo surpresita sur monero; la vera valoro estas la metalo mem, la oro. Do la valoro de homo estas lia homeco, ne lia socia rango.' WHERE id = 2081 AND ekzerco_id = 261 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Spontanea sento de inklino kaj amikeco al iu (aŭ io), kun kompreno kaj partopreno en liaj sentoj kaj suferoj.' WHERE id = 2082 AND ekzerco_id = 261 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = '“Tiel grandan kunvenon ni ankoraŭ neniam vidis!”' WHERE id = 2083 AND ekzerco_id = 262 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Svislandon reprezentis nur unu delegito.' WHERE id = 2084 AND ekzerco_id = 262 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La ekspozicio estis malfermita dum la tuta tago.' WHERE id = 2085 AND ekzerco_id = 262 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La naturbelaĵoj de nia regiono altiras ĉiujare multajn milojn da turistoj.' WHERE id = 2086 AND ekzerco_id = 262 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ni vizitis la monaĥejon, kiun la popolo konstruis antaŭ multaj jarcentoj.' WHERE id = 2087 AND ekzerco_id = 262 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'En la lastaj jaroj li ellaboris multajn protokolojn de internaciaj konferencoj.' WHERE id = 2088 AND ekzerco_id = 262 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Tiu packonferenco en 1919 faris grandan maljustaĵon. (La konkreta ago estas maljustaĵo; maljusteco estas la eco.)' WHERE id = 2089 AND ekzerco_id = 262 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ni ne povas plenumi la multajn mendojn ĝis nun ricevitajn.' WHERE id = 2090 AND ekzerco_id = 262 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Vi devas pagi nur la sendkostojn.' WHERE id = 2091 AND ekzerco_id = 262 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Tiu vojaĝo kostos al vi ducent dolarojn.' WHERE id = 2092 AND ekzerco_id = 262 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = '“Fortiris” estas tiri for, malproksimigi per ia forto aŭ devo (la taskoj de la domo devigis ŝin foriri); “ellogis” estas igi eliri per allogo, per kortuŝa influo (liaj rakontoj vekis ŝiajn larmojn). La unua esprimas devigon, la dua allogon.' WHERE id = 2122 AND ekzerco_id = 268 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = '“Ŝi dankis min, kaj diris, se mi havas amikon, kiu amas ŝin, mi nur instruu lin rakonti mian temon, kaj tio svatus ŝin.” -is: dankis, diris; -as: havas, amas; -i: rakonti; -u: instruu; -us: svatus. La ellasita konjunkcio estas “ke” (diris, ke…).' WHERE id = 2123 AND ekzerco_id = 268 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'laŭjare: laŭ la jaroj, jaron post jaro, en kronologia ordo.' WHERE id = 2124 AND ekzerco_id = 268 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = '“Krudaj malamikoj”: kruelaj, sovaĝaj, senkompataj (figura senco, aplikita al homoj). “Krudaj rokoj”: malglataj, neprilaboritaj (pli proksime al la propra senco). Do la unua estas pli metafora.' WHERE id = 2125 AND ekzerco_id = 268 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = '“Ĝi” rilatas ne al unu substantivo, sed al la tuta ago (lia trafa parolado); strikte oni atendus “tio”.' WHERE id = 2126 AND ekzerco_id = 268 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La Doĝo konsilas al Brabancio akcepti la faritan geedziĝon: pli bone estas uzi tion, kio restas, eĉ se ĝi ne estas perfekta (la rompita glavo), ol resti tute senhelpa (rifuzi kaj perdi ĉion, eĉ la filinon).' WHERE id = 2127 AND ekzerco_id = 268 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Persona opinio. Ekzemple: “Min amis ŝia patro” (objekto antaŭ la verbo, por emfazi Otelon), “kiun fragmente ŝi ja iom aŭdis”, “Tion aŭdi tre emis Desdemona”. Tiuj inversioj servas al la ritmo kaj al la emfazo.' WHERE id = 2128 AND ekzerco_id = 268 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La tuta rilata subpropozicio “kion alie per tuta koro kontraŭ vi mi gardus” (= tion, kion…), t.e. Desdemona.' WHERE id = 2129 AND ekzerco_id = 268 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = '“Ĝin” anstataŭas “infanon”: oni uzas “ĝi” por infano, kies sekso ne estas difinita (ĉi tie hipoteza infano, kiu ne ekzistas).' WHERE id = 2130 AND ekzerco_id = 268 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Persona verko. Ekzemple: “Se l’ koro kontraŭ sia sort’ ribelas, / la pacon ĝi el sia hejm’ forpelas.” “Ju pli rapide venas la kisiĝo, / des pli rapide sekvas la disiĝo.”' WHERE id = 2131 AND ekzerco_id = 268 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La nova filmo estos prezentata dum la kongreso.' WHERE id = 2151 AND ekzerco_id = 271 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La ekskurso estis tre agrabla kaj tial niaj samideanoj ne bedaŭris sian partoprenon.' WHERE id = 2152 AND ekzerco_id = 271 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ni esperas, ke vi havos agrablan vojaĝon.' WHERE id = 2153 AND ekzerco_id = 271 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Tiun konstruaĵon oni uzos kiel la centron de la japanaj studoj en Eŭropo.' WHERE id = 2154 AND ekzerco_id = 271 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Tiu prelego estis tre amuza kaj instrua.' WHERE id = 2155 AND ekzerco_id = 271 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ni ne deziras miksi nin en la disputon (aŭ: enmiksiĝi en la disputon).' WHERE id = 2156 AND ekzerco_id = 271 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ne necesas, ke la homoj mortu kaj mortigu por la patrujo.' WHERE id = 2157 AND ekzerco_id = 271 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La ministro kaj liaj kunuloj ne petis la opinion de la parlamento.' WHERE id = 2158 AND ekzerco_id = 271 AND COALESCE(respondo, '') = '';

-- 28.3 n°8 : l'énoncé contenait un double saut de ligne (CR LF CR LF) au milieu de la phrase
UPDATE ekzerceroj SET demando = REPLACE(demando, CONCAT(CHAR(13), CHAR(10), CHAR(13), CHAR(10)), ' ') WHERE id = 2129 AND ekzerco_id = 268 AND demando LIKE CONCAT('%', CHAR(13), CHAR(10), CHAR(13), CHAR(10), '%');

-- Vérification
SELECT ekzerco_id, COUNT(*) AS demandoj, SUM(COALESCE(respondo, '') <> '') AS kun_respondo FROM ekzerceroj
  WHERE ekzerco_id IN (249, 250, 254, 255, 257, 259, 261, 262, 268, 271) AND forigita = 0 GROUP BY ekzerco_id;
